  function rgbHex(h){h=String(h||'#000').replace('#','');if(h.length===3)h=h.split('').map(x=>x+x).join('');return[parseInt(h.slice(0,2),16),parseInt(h.slice(2,4),16),parseInt(h.slice(4,6),16)]}
  function corEscala(colors,t){const i=Math.max(0,Math.min(colors.length-1,Math.floor(clamp(t,0,.999999)*colors.length)));return rgbHex(colors[i])}
